/**
 * CSV parsing for the import path (REQ-1-3-1, Issue #3 decision D-A5).
 *
 * The requirement names exactly one invalid input class: a field that begins
 * with a double quote but never closes it. Everything else is accepted loosely:
 *
 * - delimiter `,`; record separators LF, CRLF and lone CR;
 * - field content is preserved verbatim (a CRLF inside a quoted field stays a
 *   CRLF, it is never normalized);
 * - only the first character of a field can open quoted mode; inside quotes
 *   `""` is one literal `"`, and `,`/newlines are literal content;
 * - text after the closing quote is appended literally (`"ab"cd` -> `abcd`);
 * - a bare `"` inside an unquoted field is a literal character;
 * - a leading UTF-8 BOM is stripped; an empty file (or BOM only) is 0 records;
 * - a trailing newline and trailing blank lines do not create a record.
 *
 * The parser is a pure function so both the import endpoint and its unit tests
 * can use it without a database.
 */

/** Invalid CSV input (the single class the requirement rejects). */
export class CsvParseError extends Error {
  constructor(message = 'Invalid CSV file format. Import failed.') {
    super(message);
    this.name = 'CsvParseError';
  }
}

/**
 * Parse CSV text into a dense array of records (`string[][]`).
 *
 * @param {string} text
 * @returns {string[][]}
 * @throws {CsvParseError} when a field opens a quote that never closes.
 */
export function parseCsv(text) {
  if (typeof text !== 'string') {
    throw new CsvParseError('CSV content must be a string');
  }

  let input = text;
  if (input.charCodeAt(0) === 0xfeff) input = input.slice(1);

  /** @type {string[][]} */
  const records = [];
  /** @type {string[]} */
  let record = [];
  let field = '';
  let quoted = false;
  /** True while no character of the current field has been consumed yet. */
  let atFieldStart = true;
  let i = 0;

  while (i < input.length) {
    const ch = input[i];

    if (quoted) {
      if (ch === '"') {
        if (input[i + 1] === '"') {
          field += '"';
          i += 2;
          continue;
        }
        quoted = false;
        i += 1;
        continue;
      }
      field += ch;
      i += 1;
      continue;
    }

    if (atFieldStart && ch === '"') {
      quoted = true;
      atFieldStart = false;
      i += 1;
      continue;
    }

    if (ch === ',') {
      record.push(field);
      field = '';
      atFieldStart = true;
      i += 1;
      continue;
    }

    if (ch === '\n' || ch === '\r') {
      if (ch === '\r' && input[i + 1] === '\n') i += 1;
      i += 1;
      record.push(field);
      records.push(record);
      record = [];
      field = '';
      atFieldStart = true;
      continue;
    }

    field += ch;
    atFieldStart = false;
    i += 1;
  }

  if (quoted) {
    throw new CsvParseError();
  }

  // A record is still buffered when the input did not end with a separator
  // (`a,b`) or when the last character was a delimiter (`a,` -> trailing empty
  // field). An input that ended exactly on a separator leaves `atFieldStart`
  // true with nothing buffered, which produces no extra record.
  if (!atFieldStart || field !== '' || record.length > 0) {
    record.push(field);
    records.push(record);
  }

  // Trailing blank lines (`a\n\n`, `\n`) are line noise, not records; a blank
  // line is a record holding exactly one empty field.
  while (records.length > 0) {
    const last = records[records.length - 1];
    if (last.length === 1 && last[0] === '') records.pop();
    else break;
  }

  return records;
}

/**
 * Column count of a parsed CSV: the widest record. Empty input is 0 columns.
 *
 * @param {string[][]} records
 * @returns {number}
 */
export function csvColumnCount(records) {
  let cols = 0;
  for (const record of records) {
    if (record.length > cols) cols = record.length;
  }
  return cols;
}

/**
 * Derive the workbook name from the uploaded file name: drop a trailing
 * `.csv` (case-insensitive), then fall back to the backend default when
 * nothing usable remains.
 *
 * @param {string} fileName
 * @param {string} fallback
 * @returns {string}
 */
export function workbookNameFromFileName(fileName, fallback) {
  const stripped = fileName.trim().replace(/\.csv$/i, '');
  const name = stripped.trim();
  return name || fallback;
}

import type { WorksheetSnapshot } from '../../../shared/types';
import type { CellDisplayValue } from './cellDisplay';
import { worksheetDisplayValues } from './cellDisplay';

/**
 * CSV serialization for REQ-1-3-2 (Issue #3 decision D-A7).
 *
 * - used range = A1 to the furthest non-empty cell (trailing all-empty rows and
 *   columns are trimmed); empty cells inside that box export as empty fields;
 *   a worksheet with no content exports an empty file;
 * - records are separated by `\n` with no trailing terminator (RFC 4180 makes a
 *   final line break optional, and a byte-exact comparison built as
 *   `rows.map((r) => r.join(',')).join('\n')` is the most common harness shape);
 *   the file carries no BOM;
 * - escaping follows RFC 4180: fields containing `,`, `"`, `\n` or `\r` are
 *   wrapped in double quotes and inner quotes are doubled.
 */

const NEEDS_QUOTES = /[",\n\r]/;

/** RFC 4180 field escaping. */
export function escapeCsvField(value: string): string {
  if (!NEEDS_QUOTES.test(value)) return value;
  return `"${value.replace(/"/g, '""')}"`;
}

/**
 * Serialize one worksheet to CSV text.
 *
 * @param worksheet the active worksheet snapshot
 * @param display the shared display-value seam (D-A8); defaults to raw text
 */
export function worksheetToCsv(
  worksheet: WorksheetSnapshot,
  display: CellDisplayValue = worksheetDisplayValues(worksheet),
): string {
  let maxRow = -1;
  let maxCol = -1;
  for (const [row, col, raw] of worksheet.cells) {
    // The box is measured from stored content. Cells with no stored raw text are
    // not in the snapshot at all, and the display seam cannot widen the used
    // range beyond what the worksheet actually holds.
    if (raw === '') continue;
    if (row > maxRow) maxRow = row;
    if (col > maxCol) maxCol = col;
  }
  if (maxRow < 0 || maxCol < 0) return '';

  const lines: string[] = [];
  for (let row = 0; row <= maxRow; row += 1) {
    const fields: string[] = [];
    for (let col = 0; col <= maxCol; col += 1) {
      fields.push(escapeCsvField(display(row, col)));
    }
    lines.push(fields.join(','));
  }
  return lines.join('\n');
}

/** Suggested download name; always ends with `.csv` as the requirement asks. */
export function csvFileName(workbookName: string): string {
  const base = workbookName.trim().replace(/[/\\:*?"<>|]/g, '_') || 'workbook';
  return /\.csv$/i.test(base) ? base : `${base}.csv`;
}

/** Trigger a same-origin browser download of the CSV text. */
export function downloadCsv(fileName: string, csv: string): void {
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  document.body.appendChild(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(url);
}

/** @typedef {import('../../shared/types.js').CellChange} CellChange */
/** @typedef {import('../../shared/types.js').CellCoord} CellCoord */
/** @typedef {import('../../shared/types.js').CellEntry} CellEntry */
/** @typedef {import('../../shared/types.js').FilterSpec} FilterSpec */
/** @typedef {import('../../shared/types.js').PivotSpec} PivotSpec */
/** @typedef {import('../../shared/types.js').SelectionRect} SelectionRect */
/** @typedef {import('../../shared/types.js').ValidationRule} ValidationRule */
/** @typedef {import('../../shared/types.js').WorkbookSnapshot} WorkbookSnapshot */
/** @typedef {import('../../shared/types.js').WorkbookSummary} WorkbookSummary */
/** @typedef {import('../../shared/types.js').WorksheetSnapshot} WorksheetSnapshot */
/** @typedef {import('../../shared/types.js').WorksheetStatePayload} WorksheetStatePayload */
/** @typedef {import('./db.js').Db} Db */

import { DEFAULT_COL_COUNT, DEFAULT_ROW_COUNT, DEFAULT_SELECTION } from './config.js';
import { csvColumnCount } from './csv.js';
import { ApiError, invalidBody, notFound, validationError } from './errors.js';
import { newId, nowIso } from './ids.js';

/**
 * @typedef {object} WorkbookRow
 * @property {string} id
 * @property {string} name
 * @property {string} created_at
 * @property {string} updated_at
 */

/**
 * @typedef {object} WorksheetRow
 * @property {string} id
 * @property {string} workbook_id
 * @property {string} name
 * @property {number} position
 * @property {number} row_count
 * @property {number} col_count
 * @property {number} last_active
 * @property {string | null} last_selection
 */

/**
 * @template T
 * @param {string | null} raw
 * @param {T} fallback
 * @returns {T}
 */
function parseJson(raw, fallback) {
  if (raw === null || raw === undefined || raw === '') return fallback;
  try {
    return /** @type {T} */ (JSON.parse(raw));
  } catch {
    return fallback;
  }
}

/**
 * @param {Db} db
 * @returns {WorkbookSummary[]}
 */
export function listWorkbooks(db) {
  const rows = /** @type {{ id: string, name: string, updated_at: string }[]} */ (
    db
      .prepare('SELECT id, name, updated_at FROM workbooks ORDER BY updated_at DESC, created_at DESC')
      .all()
  );
  return rows.map((r) => ({ id: r.id, name: r.name, updatedAt: r.updated_at }));
}

/**
 * @param {Db} db
 * @param {string} id
 * @returns {WorkbookRow | null}
 */
export function getWorkbookRow(db, id) {
  const row = /** @type {WorkbookRow | undefined} */ (
    db.prepare('SELECT * FROM workbooks WHERE id = ?').get(id)
  );
  return row ?? null;
}

/**
 * @param {Db} db
 * @param {string} id
 * @returns {WorksheetRow | null}
 */
export function getWorksheetRow(db, id) {
  const row = /** @type {WorksheetRow | undefined} */ (
    db.prepare('SELECT * FROM worksheets WHERE id = ?').get(id)
  );
  return row ?? null;
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} worksheetId
 * @returns {WorksheetRow}
 */
export function requireWorksheet(db, workbookId, worksheetId) {
  const ws = getWorksheetRow(db, worksheetId);
  if (!ws || ws.workbook_id !== workbookId) {
    throw notFound('Worksheet not found');
  }
  return ws;
}

/**
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @returns {WorksheetSnapshot}
 */
export function getWorksheetSnapshot(db, ws) {
  const cells = /** @type {{ row: number, col: number, raw: string }[]} */ (
    db
      .prepare('SELECT row, col, raw FROM cells WHERE worksheet_id = ? ORDER BY row, col')
      .all(ws.id)
  );
  const validations = /** @type {{ id: string, kind: string, range: string, params: string }[]} */ (
    db
      .prepare(
        'SELECT id, kind, range, params FROM validation_rules WHERE worksheet_id = ? ORDER BY rowid',
      )

      )
      .all(ws.id)
  );
  const filters = /** @type {{ id: string, range: string, column_specs: string }[]} */ (
    db
      .prepare('SELECT id, range, column_specs FROM filters WHERE worksheet_id = ? ORDER BY rowid')
      .all(ws.id)
  );
  const pivots = /** @type {{
   *   id: string, source_worksheet_id: string, source_range: string, config: string,
   *   result_worksheet_id: string, last_result: string | null, stale: number
   * }[]} */ (
    db
      .prepare(
        `SELECT id, source_worksheet_id, source_range, config, result_worksheet_id, last_result, stale
         FROM pivots WHERE source_worksheet_id = ? ORDER BY rowid`,
      )
      .all(ws.id)
  );

  return {
    id: ws.id,
    name: ws.name,
    position: ws.position,
    isActive: ws.last_active === 1,
    rowCount: ws.row_count,
    colCount: ws.col_count,
    cells: /** @type {CellEntry[]} */ (cells.map((c) => [c.row, c.col, c.raw])),
    lastSelection: parseJson(ws.last_selection, /** @type {SelectionRect | null} */ (null)),
    validations: validations.map((v) => ({
      id: v.id,
      kind: /** @type {ValidationRule['kind']} */ (v.kind),
      range: v.range,
      params: parseJson(v.params, /** @type {Record<string, unknown>} */ ({})),
    })),
    filters: filters.map((f) => ({
      id: f.id,
      range: f.range,
      columnSpecs: parseJson(f.column_specs, /** @type {FilterSpec['columnSpecs']} */ ([])),
    })),
    pivots: pivots.map((p) => ({
      id: p.id,
      sourceWorksheetId: p.source_worksheet_id,
      sourceRange: p.source_range,
      config: parseJson(
        p.config,
        /** @type {PivotSpec['config']} */ ({
          rowField: null,
          columnField: null,
          valueField: null,
          summarize: 'SUM',
        }),
      ),
      resultWorksheetId: p.result_worksheet_id,
      lastResult: parseJson(p.last_result, /** @type {PivotSpec['lastResult']} */ (null)),
      stale: p.stale === 1,
    })),
  };
}

/**
 * @param {Db} db
 * @param {string} id
 * @returns {WorkbookSnapshot | null}
 */
export function getWorkbookSnapshot(db, id) {
  const wb = getWorkbookRow(db, id);
  if (!wb) return null;
  const worksheets = /** @type {WorksheetRow[]} */ (
    db.prepare('SELECT * FROM worksheets WHERE workbook_id = ? ORDER BY position, rowid').all(id)
  );
  return {
    id: wb.id,
    name: wb.name,
    updatedAt: wb.updated_at,
    worksheets: worksheets.map((ws) => getWorksheetSnapshot(db, ws)),
  };
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} [at]
 * @returns {string}
 */
export function touchWorkbook(db, workbookId, at = nowIso()) {
  db.prepare('UPDATE workbooks SET updated_at = ? WHERE id = ?').run(at, workbookId);
  return at;
}

/**
 * Create a blank workbook with a single active `Sheet1` and `A1` selected.
 *
 * @param {Db} db
 * @param {string} name
 * @returns {WorkbookSnapshot}
 */
export function createWorkbook(db, name) {
  const id = newId('wb');
  const worksheetId = newId('ws');
  const at = nowIso();
  db.transaction(() => {
    db.prepare('INSERT INTO workbooks (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)').run(
      id,
      name,
      at,
      at,
    );
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      worksheetId,
      id,
      'Sheet1',
      0,
      DEFAULT_ROW_COUNT,
      DEFAULT_COL_COUNT,
      1,
      JSON.stringify(DEFAULT_SELECTION),
    );
  })();
  const snapshot = getWorkbookSnapshot(db, id);
  if (!snapshot) throw new Error('Failed to create workbook');
  return snapshot;
}

/**
 * Create a workbook from parsed CSV records in a single transaction
 * (REQ-1-3-1 / contract increment A-1). Either the workbook, its Sheet1 and
 * every cell land together, or nothing does.
 *
 * Structure (contract increment A-2): the worksheet is never smaller than the
 * default 6 x 26 structure, so an empty or tiny CSV still yields an editable
 * worksheet with a valid A1 selection and a renderable grid.
 *
 * @param {Db} db
 * @param {string} name
 * @param {string[][]} records
 * @returns {WorkbookSnapshot}
 */
export function createWorkbookFromCsv(db, name, records) {
  const id = newId('wb');
  const worksheetId = newId('ws');
  const at = nowIso();
  const rowCount = Math.max(records.length, DEFAULT_ROW_COUNT);
  const colCount = Math.max(csvColumnCount(records), DEFAULT_COL_COUNT);

  db.transaction(() => {
    db.prepare('INSERT INTO workbooks (id, name, created_at, updated_at) VALUES (?, ?, ?, ?)').run(
      id,
      name,
      at,
      at,
    );
    db.prepare(
      `INSERT INTO worksheets (id, workbook_id, name, position, row_count, col_count, last_active, last_selection)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
    ).run(
      worksheetId,
      id,
      'Sheet1',
      0,
      rowCount,
      colCount,
      1,
      JSON.stringify(DEFAULT_SELECTION),
    );
    const insert = db.prepare(
      'INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)',
    );
    for (let row = 0; row < records.length; row += 1) {
      const record = records[row];
      for (let col = 0; col < record.length; col += 1) {
        const raw = record[col];
        // Same convention as every other write path: an empty field has no row.
        if (raw !== '') insert.run(worksheetId, row, col, raw);
      }
    }
  })();

  const snapshot = getWorkbookSnapshot(db, id);
  if (!snapshot) throw new Error('Failed to create workbook from CSV');
  return snapshot;
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {unknown} rawName
 * @returns {WorkbookSummary}
 */
export function renameWorkbook(db, workbookId, rawName) {
  const wb = getWorkbookRow(db, workbookId);
  if (!wb) throw notFound('Workbook not found');
  if (typeof rawName !== 'string') throw invalidBody('Workbook name must be a string');
  const name = rawName.trim();
  if (!name) throw validationError('Workbook name cannot be empty');
  const at = nowIso();
  db.transaction(() => {
    db.prepare('UPDATE workbooks SET name = ?, updated_at = ? WHERE id = ?').run(
      name,
      at,
      workbookId,
    );
  })();
  return { id: workbookId, name, updatedAt: at };
}

/**
 * @typedef {object} CellWriteResult
 * @property {string} updatedAt
 * @property {CellChange[]} changes
 * @property {CellCoord[]} removed
 */

/**
 * Apply a batch of cell writes atomically. `raw === ''` clears the cell.
 * All-or-nothing: validation must have rejected the batch before this runs.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {CellChange[]} changes
 * @returns {CellWriteResult}
 */
export function applyCellChanges(db, ws, changes) {
  const at = nowIso();
  const upsert = db.prepare(
    `INSERT INTO cells (worksheet_id, row, col, raw) VALUES (?, ?, ?, ?)
     ON CONFLICT (worksheet_id, row, col) DO UPDATE SET raw = excluded.raw`,
  );
  const remove = db.prepare('DELETE FROM cells WHERE worksheet_id = ? AND row = ? AND col = ?');
  /** @type {CellChange[]} */
  const written = [];
  /** @type {CellCoord[]} */
  const removed = [];
  db.transaction(() => {
    for (const change of changes) {
      if (change.raw === '') {
        remove.run(ws.id, change.row, change.col);
        removed.push({ row: change.row, col: change.col });
      } else {
        upsert.run(ws.id, change.row, change.col, change.raw);
        written.push(change);
      }
    }
    touchWorkbook(db, ws.workbook_id, at);
  })();
  return { updatedAt: at, changes: written, removed };
}

/**
 * @param {Db} db
 * @param {string} workbookId
 * @param {string} worksheetId
 * @param {string} name
 * @returns {void}
 */
function assertWorksheetNameAvailable(db, workbookId, worksheetId, name) {
  const clash = /** @type {{ id: string } | undefined} */ (
    db
      .prepare('SELECT id FROM worksheets WHERE workbook_id = ? AND name = ? AND id <> ?')
      .get(workbookId, name, worksheetId)
  );
  if (clash) throw new ApiError(409, 'VALIDATION_ERROR', 'Worksheet name already exists');
}

/**
 * Rename and/or activate a worksheet. Never touches cell data.
 *
 * @param {Db} db
 * @param {WorksheetRow} ws
 * @param {{ name?: unknown, isActive?: unknown }} patch
 * @returns {{ worksheet: WorksheetSnapshot, updatedAt: string }}
 */
export function patchWorksheet(db, ws, patch) {
  /** @type {{ name?: string, isActive?: boolean }} */
  const fields = {};

  if (patch.name !== undefined) {
    if (typeof patch.name !== 'string') throw invalidBody('Worksheet name must be a string');

