import fs from 'node:fs';
import path from 'node:path';
import Database from 'better-sqlite3';
import { MIGRATIONS } from './migrations.js';
import { nowIso } from './ids.js';

/** @typedef {import('better-sqlite3').Database} Db */

/**
 * Open (creating if needed) the SQLite database and bring the schema up to date.
 *
 * @param {string} dbPath
 * @returns {Db}
 */
export function openDatabase(dbPath) {
  if (dbPath !== ':memory:') {
    fs.mkdirSync(path.dirname(dbPath), { recursive: true });
  }
  const db = new Database(dbPath);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  db.pragma('busy_timeout = 5000');
  migrate(db);
  return db;
}

/**
 * Apply pending migrations. Safe to call on every start.
 *
 * @param {Db} db
 * @returns {void}
 */
export function migrate(db) {
  db.exec(`
    CREATE TABLE IF NOT EXISTS schema_migrations (
      id         TEXT PRIMARY KEY,
      applied_at TEXT NOT NULL
    );
  `);
  const rows = /** @type {{ id: string }[]} */ (
    db.prepare('SELECT id FROM schema_migrations').all()
  );
  const applied = new Set(rows.map((r) => r.id));
  const record = db.prepare('INSERT INTO schema_migrations (id, applied_at) VALUES (?, ?)');
  for (const migration of MIGRATIONS) {
    if (applied.has(migration.id)) continue;
    db.transaction(() => {
      db.exec(migration.sql);
      record.run(migration.id, nowIso());
    })();
  }
}
